#!/usr/bin/env bash
set -euo pipefail

# GitHub-hosted Macs use Ethernet; the VM DNS proxy can retain NXDOMAIN
# for newly allocated Quick Tunnel names even after public resolvers answer.
/usr/bin/time -p sudo networksetup -setdnsservers Ethernet 1.1.1.1 8.8.8.8
/usr/bin/time -p sudo dscacheutil -flushcache
/usr/bin/time -p sudo killall -HUP mDNSResponder
/usr/bin/time -p networksetup -getdnsservers Ethernet
.omgithub/scripts/stop-lifecycle.mjs
import { existsSync, readFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { pathToFileURL } from 'node:url'

function alive(pid) {
  try {
    process.kill(pid, 0)
    // An orphaned zombie cannot run or handle signals; do not wait on it.
    if (process.platform === 'linux') {
      const stat = readFileSync(`/proc/${pid}/stat`, 'utf8')
      if (stat.slice(stat.lastIndexOf(')') + 2).startsWith('Z')) return false
    }
    return true
  } catch (error) { if (error.code === 'ESRCH' || error.code === 'ENOENT') return false; throw error }
}
const pause = ms => new Promise(resolve => setTimeout(resolve, ms))
const signal = (pid, name) => { try { process.kill(pid, name) } catch (error) { if (error.code !== 'ESRCH') throw error } }

function killGroups(directory, log) {
  try {
    const groups = JSON.parse(readFileSync(join(directory, 'lifecycle-children.json'), 'utf8'))
    for (const group of groups) if (Number.isSafeInteger(group) && group > 1) signal(-group, 'SIGKILL')
  } catch (error) { log(`Could not terminate recorded child groups: ${error.message}`) }
}

export async function stopLifecycle(pidFile, { waitMs = 210000, pollMs = 1000, log = console.error } = {}) {
  if (!existsSync(pidFile)) return
  const pid = Number(readFileSync(pidFile, 'utf8').trim())
  if (!Number.isSafeInteger(pid) || pid <= 1) throw new Error('Invalid lifecycle PID')
  const directory = dirname(pidFile)
  if (alive(pid)) {
    signal(pid, 'SIGTERM')
    const deadline = Date.now() + waitMs
    while (alive(pid) && Date.now() < deadline) await pause(Math.min(pollMs, Math.max(1, deadline - Date.now())))
    if (alive(pid)) {
      log(`Lifecycle ${pid} did not stop after ${waitMs} ms; terminating owned child groups and controller`)
      killGroups(directory, log)
      signal(pid, 'SIGKILL')
      // Preserve the failure while ensuring cleanup finishes before removing runtime files.
      const killedDeadline = Date.now() + 5000
      while (alive(pid) && Date.now() < killedDeadline) await pause(pollMs)
      throw new Error(`Lifecycle shutdown timed out after ${waitMs} ms`)
    }
  }
  const result = join(directory, 'lifecycle-shutdown.json')
  if (!existsSync(result)) {
    killGroups(directory, log)
    throw new Error('Lifecycle exited without a shutdown result; inspect lifecycle.log')
  }
  if (JSON.parse(readFileSync(result, 'utf8')).exitCode !== 0) throw new Error('Lifecycle shutdown failed; inspect lifecycle.log')
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const started = Date.now()
  try { await stopLifecycle(join(process.env.OPENCODE_WEB_DIR, 'lifecycle.pid')) }
  catch (error) { console.error(error.message); process.exitCode = 1 }
  finally { console.error(`[timing] lifecycle stop: ${Date.now() - started} ms`) }
}
.omgithub/scripts/wait-deployment.mjs
import { readFileSync, writeFileSync, appendFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { setTimeout } from 'node:timers/promises'
import { fileURLToPath } from 'node:url'

// Waits for the final main turn's delivery. When that turn asked the user a question
// (state awaiting_reply), keep waiting for a reply prompt, then re-arm on the next turn.
export async function waitForDeployment({ directory, now = Date.now, pause = setTimeout, timeoutMs = 20 * 60_000, replyTimeoutMs = 60 * 60_000, overallMs = 240 * 60_000, deadlineAt = Infinity, reconcile = async () => {}, log = () => {} }) {
  const read = name => {
    try { return JSON.parse(readFileSync(join(directory, name), 'utf8')) }
    catch (error) { if (error.code === 'ENOENT' || error instanceof SyntaxError) return null; throw error }
  }
  const completion = read('main-completion.json')
  const started = now(), hardStop = Math.min(started + overallMs, deadlineAt)
  let deadline = started + timeoutMs
  let target = completion?.message_id || null
  const answered = new Set()
  let awaiting = null, reconciliationError
  while (now() < Math.min(awaiting ? awaiting.until : deadline, hardStop)) {
    try { await reconcile(); reconciliationError = null }
    catch (error) { reconciliationError = error.message }
    const status = read('deployment-status.json')
    if (awaiting) {
      // A reply prompt starts a newer lifecycle generation (its first status still carries the old message id).
      if (status && Number(status.generation) > awaiting.generation && !(status.state === 'awaiting_reply' && status.message_id === awaiting.message_id)) {
        answered.add(awaiting.message_id)
        log(`Reply received after question ${awaiting.message_id}; waiting for the next delivery.`)
        awaiting = null; target = null; deadline = now() + timeoutMs
        continue
      }
      await pause(1000)
      continue
    }
    // An earlier turn may still be ready while the final completion is queued.
    const current = status && (target ? status.message_id === target : (!answered.size || (status.message_id && !answered.has(status.message_id))))
    if (current && status.state === 'awaiting_reply') {
      awaiting = { message_id: status.message_id, generation: Number(status.generation) || 0, until: now() + replyTimeoutMs }
      log(`OpenCode asked a question (${status.message_id}); waiting up to ${Math.round(replyTimeoutMs / 60000)} min for a reply.`)
      continue
    }
    if (current && status.state === 'failed') throw new Error(status.error || 'Production delivery failed')
    if (current && status.state === 'ready') {
      const result = read('deployment-result.json')
      if (!result?.preview_url || String(result.generation) !== String(status.generation) || !Array.isArray(result.screenshots) || result.screenshots.length < 2) throw new Error('Incomplete production delivery')
      return result
    }
    await pause(1000)
  }
  if (awaiting) return { awaiting_reply: true, message_id: awaiting.message_id }
  throw new Error(`Production delivery timed out${reconciliationError ? `: ${reconciliationError}` : ''}`)
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const env = process.env
  const jobStart = /^\d+$/.test(env.JOB_STARTED_AT || '') ? Number(env.JOB_STARTED_AT) * 1000 : Date.parse(env.JOB_STARTED_AT || '')
  try {
    const result = await waitForDeployment({ directory: env.OPENCODE_WEB_DIR, log: message => console.log(message),
      // Leave room for checkpoint and cleanup steps inside the 305-minute job timeout.
      deadlineAt: Number.isFinite(jobStart) ? jobStart + 300 * 60_000 : Infinity,
      reconcile: async () => {
        if (!env.OPENCODE_CONTROL_PORT) return
        const response = await fetch(`http://127.0.0.1:${env.OPENCODE_CONTROL_PORT}/omgithub/reconcile`, { signal: AbortSignal.timeout(10000) })
        if (!response.ok) throw new Error(`Deployment reconciliation HTTP ${response.status}`)
      } })
    if (result.awaiting_reply) {
      writeFileSync(join(env.OPENCODE_WEB_DIR, 'awaiting-ended.json'), JSON.stringify({ message_id: result.message_id, ended_at: new Date().toISOString() }))
      if (env.GITHUB_ENV) appendFileSync(env.GITHUB_ENV, 'AWAITING_REPLY_ENDED=true\n')
      console.log('No reply arrived in time; ending the session while it waits for your reply.')
    } else console.log('Production delivery completed checkpoint, capture, and deployment.')
  } catch (error) {
    if (env.OPENCODE_WEB_DIR) writeFileSync(join(env.OPENCODE_WEB_DIR, 'delivery-failure.json'), JSON.stringify({ message: error.message }))
    console.error(error.message)
    process.exit(1)
  }
}
.omgithub/scripts/start-opencode-serve.sh
#!/usr/bin/env bash
# Start (or restart) `opencode serve` on 127.0.0.1:$OPENCODE_WEB_PORT, optionally behind a local proxy relay.
# Usage: start-opencode-serve.sh [proxy-url|''] [--wait]
# Env: OPENCODE_BIN, OPENCODE_WEB_PORT, OPENCODE_WEB_DIR; --wait also needs OPENCODE_PASSWORD.
# Only `opencode serve` gets the proxy; GitHub hosts stay on the runner IP via NO_PROXY.
# The proxy must be a 127.0.0.1 relay so no credentials ever appear in argv or env.
set -uo pipefail
set +x
proxy="${1:-}" wait_ready="${2:-}"
: "${OPENCODE_BIN:?}" "${OPENCODE_WEB_PORT:?}" "${OPENCODE_WEB_DIR:?}"
if [[ -n "$proxy" && "$proxy" != http://127.0.0.1:* ]]; then echo 'start-opencode-serve: refusing a non-local proxy' >&2; exit 2; fi
pidfile="$OPENCODE_WEB_DIR/opencode.pid"
if [[ -s "$pidfile" ]]; then
  old="$(cat "$pidfile")"
  if [[ "$old" =~ ^[0-9]+$ ]] && kill -0 "$old" 2>/dev/null; then
    kill "$old" 2>/dev/null || true
    for _ in $(seq 1 50); do kill -0 "$old" 2>/dev/null || break; sleep 0.2; done
    kill -9 "$old" 2>/dev/null || true
  fi
fi
# Step-only secrets never reach the server process.
clean=(env -u GITHUB_TOKEN -u GH_TOKEN -u ACTIONS_ID_TOKEN_REQUEST_TOKEN)
if [[ -n "$proxy" ]]; then
  no_proxy_hosts='localhost,127.0.0.1,::1,github.com,.github.com,githubusercontent.com,.githubusercontent.com,githubcopilot.com,.githubcopilot.com'
  # The admin-configured backup endpoint must never go through WARP.
  backup_host="${OMG_BACKUP_HOST:-}"
  if [[ -z "$backup_host" && -s "$OPENCODE_WEB_DIR/backup-host" ]]; then backup_host="$(tr -d '[:space:]' < "$OPENCODE_WEB_DIR/backup-host")"; fi
  [[ "$backup_host" =~ ^[A-Za-z0-9.-]+$ ]] && no_proxy_hosts="$no_proxy_hosts,$backup_host"
  clean+=(HTTPS_PROXY="$proxy" HTTP_PROXY="$proxy" https_proxy="$proxy" http_proxy="$proxy" NO_PROXY="$no_proxy_hosts" no_proxy="$no_proxy_hosts")
else
  clean+=(-u HTTPS_PROXY -u HTTP_PROXY -u https_proxy -u http_proxy)
fi
nohup "${clean[@]}" "$OPENCODE_BIN" serve --hostname 127.0.0.1 --port "$OPENCODE_WEB_PORT" >> "$OPENCODE_WEB_DIR/opencode.log" 2>&1 &
echo $! > "$pidfile"
printf '%s\n' "$proxy" > "$OPENCODE_WEB_DIR/opencode-proxy"
[[ "$wait_ready" == --wait ]] || exit 0
for _ in $(seq 1 45); do
  if curl -fsS --max-time 3 -u "opencode:${OPENCODE_PASSWORD:-}" "http://127.0.0.1:$OPENCODE_WEB_PORT/api/info" > /dev/null 2>&1; then exit 0; fi
  sleep 1
done
echo 'start-opencode-serve: server did not become healthy' >&2
exit 1
