      }
      open = true
      ee.emit('open')
      if (!buffer.length) return
    }
    while (buffer.length >= 2) {
      const b0 = buffer[0], b1 = buffer[1]
      const opcode = b0 & 0x0f
      const masked = (b1 & 0x80) !== 0
